/**
 * @glidepath/testkit — SYNTHETIC test data.
 *
 * Everything here is generated by a simple kinematic model. It exists only to
 * exercise the flight engine and the Bridge without a simulator. It is NOT
 * real flight data and must never be shown to users as real. Files written
 * from it are named SYNTHETIC-*.
 *
 * Airport/runway coordinates below are approximate.
 */
import { emptyFrame, type TelemetryFrame } from "@glidepath/protocol";
import { bearingDeg, computeTopOfDescent, destinationPoint, distanceNm, type LatLon, type RunwayEnd } from "@glidepath/flight-engine";

export const SYNTHETIC_NOTICE = "SYNTHETIC test flight generated by @glidepath/testkit — not real flight data";

export const EGLL_27R: RunwayEnd = { ident: "27R", threshold: { lat: 51.4775, lon: -0.4335 }, headingTrueDeg: 269.7, lengthFt: 12800, widthFt: 164 };
export const EGCC_23R: RunwayEnd = { ident: "23R", threshold: { lat: 53.3713, lon: -2.2545 }, headingTrueDeg: 232.0, lengthFt: 10000, widthFt: 148 };
const EGLL_ELEV = 83;
const EGCC_ELEV = 257;

export interface SyntheticOptions {
  startT?: number;
  /** Seconds between frames. */
  dtS?: number;
  cruiseFt?: number;
  touchdownVsFpm?: number;
  /** Seconds the aircraft is airborne again after first contact (0 = no bounce). */
  bounceS?: number;
  touchdownG?: number;
  /** Lateral offset of the touchdown from centreline, ft (positive = right). */
  touchdownOffsetFt?: number;
  /** Insert a sim pause of this many seconds in cruise. */
  pauseInCruiseS?: number;
}

interface State {
  t: number;
  pos: LatLon;
  alt: number;
  hdg: number;
  ias: number;
  gs: number;
  vs: number;
  pitch: number;
  bank: number;
  onGround: boolean;
  gear: boolean;
  flaps: number;
  spoilers: number;
  brake: boolean;
  pushback: boolean;
  engines: boolean;
  fuelKg: number;
  ffKgH: number;
  n1: number;
  g: number;
  tdVs: number | null;
  paused: boolean;
}

/** Generate a complete EGLL → EGCC flight, gate to gate. */
export function generateSyntheticFlight(opts: SyntheticOptions = {}): TelemetryFrame[] {
  const dt = opts.dtS ?? 0.5;
  const cruiseFt = opts.cruiseFt ?? 24000;
  const tdVs = opts.touchdownVsFpm ?? 140;
  const frames: TelemetryFrame[] = [];
  const recip = (EGLL_27R.headingTrueDeg + 180) % 360;
  const stand = destinationPoint(EGLL_27R.threshold, recip, 0.7);
  const iaf = destinationPoint(EGCC_23R.threshold, (EGCC_23R.headingTrueDeg + 180) % 360, 14);
  const route: LatLon[] = [EGLL_27R.threshold, iaf, EGCC_23R.threshold];
  const routeTotal = distanceNm(route[0]!, route[1]!) + distanceNm(route[1]!, route[2]!);

  const s: State = {
    t: opts.startT ?? Date.UTC(2026, 10, 1, 10, 0, 0),
    pos: stand, alt: EGLL_ELEV, hdg: EGLL_27R.headingTrueDeg, ias: 0, gs: 0, vs: 0, pitch: 0.5, bank: 0,
    onGround: true, gear: true, flaps: 0, spoilers: 0, brake: true, pushback: false, engines: false,
    fuelKg: 6200, ffKgH: 0, n1: 0, g: 1, tdVs: null, paused: false,
  };
  let seq = 0;
  let distFlown = 0;
  let wp = 1;

  const elevAt = () => EGLL_ELEV + (EGCC_ELEV - EGLL_ELEV) * Math.min(1, distFlown / routeTotal);
  const emit = () => frames.push(toFrame(s, seq++, elevAt()));
  const move = (secs: number, speedKt: number, backwards = false) => {
    const d = (speedKt * secs) / 3600;
    s.pos = destinationPoint(s.pos, backwards ? (s.hdg + 180) % 360 : s.hdg, d);
    if (!s.onGround || speedKt > 30) distFlown += d;
  };
  const burn = (secs: number) => { s.fuelKg = Math.max(0, s.fuelKg - (s.ffKgH * secs) / 3600); };
  const step = (secs: number, fn: () => void) => {
    for (let e = 0; e < secs; e += dt) { fn(); burn(dt); s.t += dt * 1000; emit(); }
  };

  // 1. Parked, engines start after 30 s.
  step(30, () => {});
  s.engines = true; s.ffKgH = 2 * 280; s.n1 = 20;
  step(30, () => {});
  // 2. Pushback.
  s.brake = false; s.pushback = true;
  step(60, () => { s.gs = 3; move(dt, 3, true); });
  s.pushback = false; s.gs = 0;
  step(20, () => {});
  // 3. Taxi to the threshold.
  s.flaps = 1;
  const taxiDist = distanceNm(s.pos, EGLL_27R.threshold);
  step(Math.round((taxiDist / 15) * 3600), () => { s.gs = 15; s.ias = 12; s.n1 = 30; move(dt, 15); });
  s.pos = { ...EGLL_27R.threshold }; s.gs = 0; s.ias = 0;
  step(20, () => {});
  // 4. Takeoff roll and rotation.
  s.ffKgH = 2 * 1600; s.n1 = 90;
  while (s.gs < 150) step(dt, () => { s.gs += 4 * dt; s.ias = s.gs - 5; move(dt, s.gs); if (s.gs > 140) s.pitch = Math.min(15, s.pitch + 5 * dt); });
  s.onGround = false;
  // 5. Climb.
  const navigate = () => {
    const target = route[wp]!;
    if (wp < route.length - 1 && distanceNm(s.pos, target) < 2) wp++;
    const want = bearingDeg(s.pos, route[wp]!);
    let diff = ((want - s.hdg + 540) % 360) - 180;
    diff = Math.max(-3 * dt, Math.min(3 * dt, diff));
    s.hdg = (s.hdg + diff + 360) % 360;
    s.bank = diff / dt * 8;
  };
  const tasFor = (ias: number, alt: number) => ias * (1 + (alt / 1000) * 0.02);
  const remaining = () => {
    const toWp = distanceNm(s.pos, route[wp]!);
    return wp === 1 ? toWp + distanceNm(route[1]!, route[2]!) : toWp;
  };
  let gearUpAt = s.t + 6000;
  while (s.alt < cruiseFt - 5) {
    step(dt, () => {
      navigate();
      if (s.t > gearUpAt) { s.gear = false; s.flaps = s.alt > 3000 ? 0 : 1; }
      const targetVs = s.alt < 10000 ? 2500 : s.alt < cruiseFt - 2000 ? 2000 : 1000;
      s.vs += Math.max(-200 * dt, Math.min(200 * dt, targetVs - s.vs));
      s.alt = Math.min(cruiseFt, s.alt + (s.vs / 60) * dt);
      s.ias = s.alt < 10000 ? Math.min(250, s.ias + 2 * dt) : Math.min(290, s.ias + 1 * dt);
      s.gs = tasFor(s.ias, s.alt) - 15;
      s.pitch = 4 + s.vs / 1000;
      s.ffKgH = 2 * 1300;
      s.n1 = 88;
      move(dt, s.gs);
    });
  }
  s.vs = 0;
  // 6. Cruise until the (estimated) top of descent.
  let paused = false;
  const todDistance = () => computeTopOfDescent({ currentAltitudeFt: s.alt, groundSpeedKt: s.gs, target: { distanceNm: remaining(), altitudeFt: EGCC_ELEV + 3000 } }).distanceToTodNm;
  while (todDistance() > 0) {
    step(dt, () => {
      navigate(); s.vs = 0; s.pitch = 2.5; s.ffKgH = 2 * 1150; s.n1 = 82; s.ias = 290; s.gs = tasFor(290, s.alt) - 20;
      move(dt, s.gs);
    });
    if (!paused && opts.pauseInCruiseS && remaining() < routeTotal * 0.6) {
      paused = true;
      s.paused = true;
      step(opts.pauseInCruiseS, () => {});
      s.paused = false;
    }
  }
  // 7. Descent to 3000 ft above the field.
  while (s.alt > EGCC_ELEV + 3000) {
    step(dt, () => {
      navigate();
      s.vs += Math.max(-150 * dt, Math.min(150 * dt, -2000 - s.vs));
      s.alt += (s.vs / 60) * dt;
      s.ias = s.alt > 10000 ? 290 : Math.max(220, s.ias - 1 * dt);
      s.gs = tasFor(s.ias, s.alt) - 10; s.pitch = 0; s.ffKgH = 2 * 350; s.n1 = 35;
      move(dt, s.gs);
    });
  }
  // 8. Approach: fly to the IAF level, then intercept a 3° path to the threshold.
  s.gear = true; s.flaps = 3;
  while (wp === 1) step(dt, () => { navigate(); s.vs = 0; s.ias = Math.max(180, s.ias - 1 * dt); s.gs = s.ias; s.pitch = 3; s.ffKgH = 2 * 500; move(dt, s.gs); });
  s.flaps = 5;
  for (;;) {
    const d = distanceNm(s.pos, EGCC_23R.threshold);
    const pathAlt = EGCC_ELEV + 50 + d * 318; // 3° ≈ 318 ft/nm, crossing the threshold at 50 ft
    if (s.alt - EGCC_ELEV <= 30) break;
    step(dt, () => {
      navigate();
      s.ias = Math.max(140, s.ias - 1 * dt); s.gs = s.ias - 8;
      // Hold altitude until the 3° path is intercepted from below, then track it.
      s.vs = s.alt < pathAlt - 20 ? 0 : Math.max(-1500, Math.min(0, -s.gs * 5.3 + (pathAlt - s.alt) * 2));
      s.alt = Math.max(EGCC_ELEV + 29, s.alt + (s.vs / 60) * dt);
      s.pitch = 2.5; s.ffKgH = 2 * 450; s.n1 = 55;
      move(dt, s.gs);
    });
  }
  // 9. Flare and touchdown.
  const offsetNm = (opts.touchdownOffsetFt ?? 0) / 6076.12;
  if (offsetNm) s.pos = destinationPoint(s.pos, (EGCC_23R.headingTrueDeg + 90) % 360, offsetNm);
  s.hdg = EGCC_23R.headingTrueDeg; s.bank = 0;
  while (s.alt - EGCC_ELEV > 0.5) {
    step(dt, () => {
      const agl = s.alt - EGCC_ELEV;
      s.vs = -Math.max(tdVs, Math.min(700, agl * 25));
      s.alt = Math.max(EGCC_ELEV, s.alt + (s.vs / 60) * dt);
      s.pitch = Math.min(6, s.pitch + 1 * dt); s.n1 = 30; s.gs -= 0.5 * dt;
      move(dt, s.gs);
    });
  }
  s.alt = EGCC_ELEV; s.onGround = true; s.tdVs = tdVs; s.g = opts.touchdownG ?? 1.12; s.spoilers = 100;
  step(dt, () => { move(dt, s.gs); });
  s.g = 1.02;
  if (opts.bounceS && opts.bounceS > 0) {
    s.onGround = false; s.tdVs = null;
    step(opts.bounceS / 2, () => { s.alt += 3 * dt; move(dt, s.gs); });
    step(opts.bounceS / 2, () => { s.alt = Math.max(EGCC_ELEV, s.alt - 3 * dt); move(dt, s.gs); });
    s.alt = EGCC_ELEV; s.onGround = true; s.g = 1.25;
    step(dt, () => move(dt, s.gs));
    s.g = 1.0;
  }
  s.tdVs = tdVs;
  // 10. Rollout and taxi in.
  s.vs = 0; s.pitch = 0.5; s.ffKgH = 2 * 300;
  while (s.gs > 18) step(dt, () => { s.gs -= 3 * dt; s.ias = s.gs; move(dt, s.gs); });
  s.spoilers = 0; s.flaps = 0;
  step(120, () => { s.gs = 15; s.ias = 12; s.n1 = 28; move(dt, 15); });
  s.gs = 0; s.ias = 0;
  step(10, () => {});
  s.brake = true;
  step(25, () => {});
  s.engines = false; s.ffKgH = 0; s.n1 = 0;
  step(40, () => {});
  return frames;
}

function toFrame(s: State, seq: number, elev: number): TelemetryFrame {
  const f = emptyFrame(seq, Math.round(s.t), s.pos.lat, s.pos.lon);
  f.position.altMslFt = round(s.alt, 1);
  f.position.altAglFt = round(Math.max(0, s.alt - elev), 1);
  f.position.onGround = s.onGround;
  f.attitude = { pitchDeg: round(s.pitch, 2), bankDeg: round(s.bank, 2), headingTrueDeg: round(s.hdg, 2), headingMagDeg: round((s.hdg + 1 + 360) % 360, 2) };
  f.speed = { iasKt: round(s.ias, 1), tasKt: round(s.ias * (1 + (s.alt / 1000) * 0.02), 1), gsKt: round(s.gs, 1), mach: round((s.ias * (1 + (s.alt / 1000) * 0.02)) / 661, 3), vsFpm: round(s.vs, 0) };
  f.environment = { windDirDeg: 250, windKt: 20, oatC: round(15 - (s.alt / 1000) * 2, 1), qnhHpa: 1013 };
  f.loads = { gForce: s.g, touchdownVsFpm: s.tdVs };
  f.engines = [0, 1].map(() => ({ running: s.engines, n1Pct: s.engines ? s.n1 : 0, n2Pct: s.engines ? Math.min(100, s.n1 + 10) : 0, egtC: s.engines ? 350 + s.n1 * 4 : 20, fuelFlowKgH: s.ffKgH / 2 }));
  f.fuel = { totalKg: round(s.fuelKg, 1), totalFlowKgH: s.ffKgH };
  f.controls = { gearDown: s.gear, flapsIndex: s.flaps, flapsPct: s.flaps * 20, spoilersPct: s.spoilers, parkingBrake: s.brake, pushbackActive: s.pushback };
  f.autopilot = { master: !s.onGround && s.alt > 1500, flightDirector: true, headingHold: false, selectedHeadingDeg: round(s.hdg, 0), selectedAltitudeFt: 24000, selectedVsFpm: 0, selectedSpeedKt: 290, selectedMach: null, navHold: !s.onGround, approachHold: false, autothrottle: !s.onGround };
  f.lights = { nav: true, beacon: s.engines, strobe: !s.onGround || s.gs > 40, landing: s.alt - elev < 10000 && (s.gs > 40 || !s.onGround), taxi: s.onGround && s.gs > 2, logo: true, wing: false };
  f.electrical = { battery: true, externalPower: !s.engines && s.onGround, apuRpmPct: s.engines ? 0 : 100 };
  f.radios = { com1ActiveMhz: 118.5, com1StandbyMhz: 121.9, com2ActiveMhz: 121.5, com2StandbyMhz: 122.8, nav1ActiveMhz: 109.5, nav1StandbyMhz: 113.6, nav2ActiveMhz: 110.9, nav2StandbyMhz: 115.3 };
  f.sim = { paused: s.paused, simRate: 1, slew: false };
  return f;
}

const round = (v: number, dp: number) => Math.round(v * 10 ** dp) / 10 ** dp;
